import {
  APPROVAL_GATES,
  resolveModel,
  TEAM_ROLES,
  type McpServer,
  type Model,
  type RoleId,
  type TeamConfig,
} from "@agent-team/schema";
import { stringify as stringifyYaml } from "yaml";
import type { Catalog } from "./catalog.js";

export const GENERATED_MARKER =
  "Generated by agent-team from team.json. Edit team.json and run `agent-team apply` instead of editing this file.";

export const PATHS = {
  agentsDir: ".claude/agents",
  command: ".claude/commands/team.md",
  claudeMd: "CLAUDE.md",
  mcpJson: ".mcp.json",
  manifest: ".claude/agent-team.json",
} as const;

/** Model for agents that have neither their own model, a team default nor a catalog default. */
const FALLBACK_MODEL: Model = "sonnet";

export type AgentSummary = {
  name: string;
  title: string;
  model: Model;
  description: string;
  kind: "role" | "specialist";
  tools: string[];
};

export type GeneratedFile = { path: string; content: string };

export type McpUse = {
  name: string;
  specialist: string;
  server: McpServer;
  /** Environment variables the server needs (from the catalog and any env references). */
  requires: string[];
  note?: string;
};

/** Every environment variable an MCP server definition refers to. */
export function envVarsIn(server: McpServer): string[] {
  const found = new Set<string>();
  const scan = (text: string) => {
    for (const m of text.matchAll(/\$\{(\w+)\}|\{env:(\w+)\}|^env:(\w+)$/g))
      found.add((m[1] ?? m[2] ?? m[3])!);
  };
  if (server.type === "http") {
    scan(server.url);
    Object.values(server.headers).forEach(scan);
  } else {
    scan(server.command);
    server.args.forEach(scan);
    Object.values(server.env).forEach(scan);
  }
  return [...found];
}

export type Generated = {
  /** Files agent-team owns outright: written on every apply, removed when no longer needed. */
  files: GeneratedFile[];
  /** Body of the managed section in CLAUDE.md (without the markers). */
  claudeSection: string;
  /** Servers agent-team manages in .mcp.json, keyed by name, in .mcp.json format. */
  mcpServers: Record<string, Record<string, unknown>>;
  /** MCP servers in use, with what they need, for `agent-team doctor`. */
  mcp: McpUse[];
  /** Starter files for the shared workspace, only created if missing. */
  workspace: GeneratedFile[];
  agents: AgentSummary[];
  /** Each agent's full prompt (the body of its file), for the Agent SDK runner. */
  prompts: Record<string, string>;
  pmModel: Model;
  warnings: string[];
};

export class GenerateError extends Error {}

const GATE_TEXT: Record<(typeof APPROVAL_GATES)[number], string> = {
  requirements: "agreeing the requirements, before design starts",
  architecture: "settling the design, before building starts",
  estimate: "sharing estimates or scope",
  "customer-facing-docs": "sending anything a customer will see",
  merge: "merging code into the main branch",
  release: "releasing or deploying",
};

/** Fill {{placeholders}}. Unknown placeholders are a bug in the catalog, so they throw. */
export function render(template: string, vars: Record<string, string>): string {
  return template.replace(/\{\{(\w+)\}\}/g, (_, key: string) => {
    const value = vars[key];
    if (value === undefined) throw new GenerateError(`Unknown placeholder {{${key}}}`);
    return value;
  });
}

function approvalText(config: TeamConfig): string {
  const gates = config.workflow.humanApproval;
  if (gates.length === 0) return "nothing: carry on without stopping, but keep reporting progress";
  return gates.map((g) => `${g} (${GATE_TEXT[g]})`).join("; ");
}

function workspaceDir(config: TeamConfig): string {
  const ws = config.workflow.workspace;
  return ws.endsWith("/") ? ws : `${ws}/`;
}

function agentFile(agent: AgentSummary, prompt: string): GeneratedFile {
  const frontmatter = stringifyYaml(
    {
      name: agent.name,
      description: agent.description,
      tools: agent.tools.join(", "),
      model: agent.model,
    },
    { lineWidth: 0 },
  );
  return {
    path: `${PATHS.agentsDir}/${agent.name}.md`,
    content: `---\n${frontmatter}---\n\n<!-- ${GENERATED_MARKER} -->\n\n${prompt.trim()}\n`,
  };
}

function withAppend(prompt: string, append: string | undefined): string {
  if (!append?.trim()) return prompt;
  return `${prompt.trim()}\n\n## Project-specific instructions\n\n${append.trim()}`;
}

/** .mcp.json expands ${VAR}; team.json writes env:VAR and {env:VAR}. */
export function toMcpJson(server: McpServer): Record<string, unknown> {
  if (server.type === "http") {
    const headers = Object.fromEntries(
      Object.entries(server.headers).map(([k, v]) => [k, v.replace(/\{env:(\w+)\}/g, "${$1}")]),
    );
    return { type: "http", url: server.url, ...(Object.keys(headers).length ? { headers } : {}) };
  }
  const env = Object.fromEntries(
    Object.entries(server.env).map(([k, v]) => [k, `\${${v.slice("env:".length)}}`]),
  );
  return {
    type: "stdio",
    command: server.command,
    args: server.args,
    ...(Object.keys(env).length ? { env } : {}),
  };
}

export function generate(config: TeamConfig, catalog: Catalog): Generated {
  const warnings: string[] = [];
  const ws = workspaceDir(config);
  const baseVars = {
    project: config.project.name,
    workspace: ws,
    approvalGates: approvalText(config),
  };
  const agents: AgentSummary[] = [];
  const files: GeneratedFile[] = [];
  const mcpServers: Generated["mcpServers"] = {};
  const mcpUses: McpUse[] = [];
  const prompts: Record<string, string> = {};

  // Roles -------------------------------------------------------------------
  const roleIds = [...catalog.roles.keys()];
  for (const id of Object.keys(config.roles) as RoleId[]) {
    if (!catalog.roles.has(id)) throw new GenerateError(`Role "${id}" isn't in the catalog`);
  }
  for (const id of roleIds) {
    const roleConfig = config.roles[id];
    const def = catalog.roles.get(id)!;
    if (!roleConfig?.enabled || def.mainSession) continue;

    const count = TEAM_ROLES.includes(id) ? (roleConfig.count ?? 1) : 1;
    const model = resolveModel(roleConfig.model, config.defaults.model, def.defaultModel);
    const tools = roleConfig.tools ?? def.tools;
    const prompt = withAppend(render(def.prompt, baseVars), roleConfig.promptAppend);

    for (let n = 1; n <= count; n++) {
      const numbered = count > 1;
      const agent: AgentSummary = {
        name: numbered ? `${id}-${n}` : id,
        title: numbered ? `${def.title} ${n}` : def.title,
        model,
        description: numbered
          ? `${def.description} (${def.title} ${n} of ${count}.)`
          : def.description,
        kind: "role",
        tools: [...tools],
      };
      const note = numbered
        ? `\n\nYou are ${def.title.toLowerCase()} ${n} of ${count}. The others may be working in the same project at the same time on different tasks, so stay within the files your task names.`
        : "";
      agents.push(agent);
      prompts[agent.name] = (prompt + note).trim();
      files.push(agentFile(agent, prompt + note));
    }
  }

  // Specialists -------------------------------------------------------------
  for (const spec of config.specialists) {
    if (!spec.enabled) continue;
    const custom = spec.id.startsWith("custom:");
    const slug = custom ? spec.id.slice("custom:".length) : spec.id;
    const def = custom ? undefined : catalog.specialists.get(spec.id);
    if (!custom && !def) {
      const known = [...catalog.specialists.keys()].join(", ") || "none yet";
      throw new GenerateError(
        `Specialist "${spec.id}" isn't in the catalog (available: ${known}). Use "custom:${spec.id}" to describe your own.`,
      );
    }
    const title = spec.title ?? def!.title;
    const description = spec.description ?? def!.description;
    const docs = spec.docs ?? def?.docs ?? [];
    const tools = [
      ...(spec.tools ??
        def?.tools ?? ["Read", "Grep", "Glob", "Write", "Edit", "WebFetch", "WebSearch"]),
    ];

    let mcp: { name: string; server: McpServer; requires?: string[]; note?: string } | undefined;
    if (typeof spec.mcp === "object") mcp = { name: slug, server: spec.mcp };
    else if (spec.mcp === true) {
      if (def?.mcp) mcp = def.mcp;
      else
        warnings.push(
          `Specialist "${spec.id}" has "mcp": true but the catalog has no MCP server for it.`,
        );
    }
    if (mcp) {
      const server = toMcpJson(mcp.server);
      const existing = mcpServers[mcp.name];
      // Specialists may share a server (e.g. Microsoft Learn docs), but only an identical one.
      if (existing && JSON.stringify(existing) !== JSON.stringify(server)) {
        throw new GenerateError(
          `Two specialists use the MCP server name "${mcp.name}" with different settings`,
        );
      }
      mcpServers[mcp.name] = server;
      mcpUses.push({
        name: mcp.name,
        specialist: spec.id,
        server: mcp.server,
        requires: [...new Set([...(mcp.requires ?? []), ...envVarsIn(mcp.server)])],
        ...(mcp.note ? { note: mcp.note } : {}),
      });
      const toolName = `mcp__${mcp.name}`;
      if (!tools.includes(toolName)) tools.push(toolName);
    }

    const agent: AgentSummary = {
      name: `${slug}-specialist`,
      title: `${title} specialist`,
      model: resolveModel(spec.model, config.defaults.model, def?.defaultModel ?? FALLBACK_MODEL),
      description,
      kind: "specialist",
      tools,
    };
    const prompt = render(catalog.templates.specialist, {
      ...baseVars,
      title,
      description,
      knowledge: def ? render(def.prompt, baseVars) : "",
      docs: docs.length ? `Start with:\n${docs.map((d) => `  - ${d}`).join("\n")}` : "",
    }).replace(/\n{3,}/g, "\n\n");
    agents.push(agent);
    prompts[agent.name] = withAppend(prompt, spec.promptAppend).trim();
    files.push(agentFile(agent, prompts[agent.name]!));
  }

  const names = new Set<string>();
  for (const a of agents) {
    if (names.has(a.name)) throw new GenerateError(`Two agents would both be called "${a.name}"`);
    names.add(a.name);
  }

  // PM: CLAUDE.md section and /team command ---------------------------------
  const pmConfig = config.roles.pm;
  const pmDef = catalog.roles.get("pm");
  if (!pmDef) throw new GenerateError('The catalog has no "pm" role');
  const pmModel = resolveModel(pmConfig?.model, config.defaults.model, pmDef.defaultModel);

  const roster = agents.length
    ? [
        "| Agent | Role | Model | Use for |",
        "| --- | --- | --- | --- |",
        ...agents.map(
          (a) =>
            `| \`${a.name}\` | ${a.title} | ${a.model} | ${a.description.replace(/\|/g, "\\|")} |`,
        ),
      ].join("\n")
    : "No other agents are switched on, so do the work yourself.";

  const claudeSection = render(catalog.templates.claudeSection, {
    ...baseVars,
    pmPrompt: withAppend(render(pmDef.prompt, baseVars), pmConfig?.promptAppend),
    roster,
  });

  const commandFrontmatter = stringifyYaml(
    {
      description: `Hand a goal to the ${config.project.name} agent team, led by the project manager`,
      "argument-hint": "<goal>",
      ...(pmModel === "inherit" ? {} : { model: pmModel }),
    },
    { lineWidth: 0 },
  );
  files.push({
    path: PATHS.command,
    content: `---\n${commandFrontmatter}---\n\n<!-- ${GENERATED_MARKER} -->\n\n${render(catalog.templates.teamCommand, baseVars)}\n`,
  });

  // Workspace starter files -------------------------------------------------
  const workspace: GeneratedFile[] = [
    {
      path: `${ws}brief.md`,
      content: `# Brief: ${config.project.name}\n\n${config.project.summary ?? "The PM writes the goal here."}\n`,
    },
    {
      path: `${ws}backlog.md`,
      content:
        "# Backlog\n\n| Task | Owner | Status | Acceptance criteria |\n| --- | --- | --- | --- |\n",
    },
    {
      path: `${ws}decisions/README.md`,
      content:
        "# Decisions\n\nOne file per significant decision: `0001-short-title.md` with context, options, decision and consequences.\n",
    },
  ];

  files.sort((a, b) => a.path.localeCompare(b.path));
  return {
    files,
    claudeSection,
    mcpServers,
    mcp: mcpUses,
    workspace,
    agents,
    prompts,
    pmModel,
    warnings,
  };
}
